name: Clouseau
description: Exact coverage gates and evidence-led PR intent, approval, and auto-merge
inputs:
  operation:
    description: verify-engine, test, coverage, await-verification, verify-local, assess, gate, repair, check-provider, evaluate-review, evaluate-acceptance, request-reassessment, finalize, plan-wiki, publish-wiki, or evaluate-wiki
    required: true
  wait-for-verification:
    description: Keep the read-only assessment pending until real PR verification completes
    default: 'true'
  native-gate:
    description: Require the native approve-and-merge job; finalize merge in a separate job
    default: 'true'
  config:
    description: Trusted repository configuration path (assess and gate)
    default: .github/clouseau.json
  coverage-report:
    description: Native LLVM, Istanbul or coverage.py JSON report, or Go cover profile, path (coverage)
    default: ''
  coverage-config:
    description: Accepted-base version 2 local recipe with separate native coverage parts (coverage); read as data only
    default: ''
  coverage-format:
    description: llvm, istanbul, coveragepy or go; require the complete application source inventory
    default: llvm
  source-directory:
    description: Application source directory to measure (coverage)
    default: ''
  pull-request:
    description: PR number for manual reassessment
    default: ''
  assessment:
    description: Exact assessment JSON from the read-only assessment job (gate)
    default: ''
  record-transport:
    description: artifact (default) or bounded job-output record transport for v2 assess, verify-local, gate, and repair
    default: artifact
  review-record:
    description: Exact opaque review-record output from the same assessment run and attempt (canonical JSON array of four bounded base64url chunks); data only
    default: ''
  provider-key:
    description: DeepSeek API key; supply only to assess, check-provider, evaluate-review, evaluate-acceptance, plan-wiki, or evaluate-wiki
    default: ''
  typesafe-key:
    description: TypeSafe API key; supply only to the read-only assessment or acceptance qualification that uses Jev grading
    default: ''
  repair-token:
    description: Independent GitHub author token for bounded repairs; supply only to the separate repair job
    default: ''
  github-token:
    description: Caller-scoped GitHub token; permissions belong to the calling job
    default: ${{ github.token }}
  wiki-config:
    description: Trusted wiki maintenance configuration in the source checkout
    default: .github/clouseau-wiki.json
  wiki-directory:
    description: Initialized wiki Git checkout
    default: wiki
  wiki-source-directory:
    description: Git checkout of the deployment revision
    default: .
  wiki-plan-path:
    description: Validated JSON bundle produced or consumed by wiki operations
    default: work/wiki-plan.json
  wiki-draft:
    description: Generate a draft without requiring deployment; publish-wiki always requires deployment
    default: 'false'
outputs:
  assessment:
    description: Commit-bound intent decision from assess
    value: ${{ steps.assess.outputs.assessment }}
  review-record:
    description: Opaque JSON array of four bounded base64url-gzip chunks bound to repository, run, attempt, head, base, and assessment digests
    value: ${{ steps.assess.outputs.review-record }}
  verified:
    description: "'true' when PR verification succeeded; 'false' when it had not started within the queue grace and the review should end pending (await-verification)"
    value: ${{ steps.await.outputs.verified }}
  wiki-commit:
    description: Published or already-documented wiki commit
    value: ${{ steps.publish-wiki.outputs.commit }}
  wiki-pages:
    description: Number of changed Markdown pages
    value: ${{ steps.publish-wiki.outputs.pages }}
runs:
  using: composite
  steps:
    - name: Validate Clouseau operation
      shell: bash
      env:
        CLOUSEAU_OPERATION: ${{ inputs.operation }}
        CLOUSEAU_RECORD_TRANSPORT: ${{ inputs.record-transport }}
        CLOUSEAU_HAS_REVIEW_RECORD: ${{ inputs.review-record != '' }}
      run: |
        case "$CLOUSEAU_OPERATION" in
          verify-engine|test|coverage|await-verification|verify-local|assess|gate|repair|check-provider|evaluate-review|evaluate-acceptance|request-reassessment|finalize|plan-wiki|publish-wiki|evaluate-wiki) ;;
          *) echo 'Unknown Clouseau operation' >&2; exit 1 ;;
        esac
        case "$CLOUSEAU_RECORD_TRANSPORT" in
          artifact) test "$CLOUSEAU_HAS_REVIEW_RECORD" = false ;;
          job-output)
            case "$CLOUSEAU_OPERATION" in
              assess|verify-local) test "$CLOUSEAU_HAS_REVIEW_RECORD" = false ;;
              gate|repair) test "$CLOUSEAU_HAS_REVIEW_RECORD" = true ;;
              *) echo 'Job-output transport requires assess, verify-local, gate, or repair' >&2; exit 1 ;;
            esac ;;
          *) echo 'Unknown Clouseau record transport' >&2; exit 1 ;;
        esac
    - name: Verify and record this run frozen engine
      uses: actions/github-script@v7
      env:
        CLOUSEAU_ROOT: ${{ github.action_path }}
      with:
        script: |
          const fs = require('node:fs');
          const path = require('node:path');
          const engine = require(path.join(process.env.CLOUSEAU_ROOT, 'src/central-version.cjs')).environmentEngine();
          if (engine) {
            fs.mkdirSync('work', {recursive: true});
            fs.writeFileSync('work/clouseau-engine.json', JSON.stringify(engine, null, 2) + '\n');
            await core.summary.addRaw(`Clouseau frozen commit: ${engine.sha}\n\nEngine digest: ${engine.digest}\n`).write();
          }
    - name: Test approval policy
      if: inputs.operation == 'test'
      shell: bash
      working-directory: ${{ github.action_path }}
      run: |
        node --test src/*.test.cjs
    - name: Enforce 100% line and branch coverage
      if: inputs.operation == 'coverage'
      shell: bash
      env:
        CLOUSEAU_ROOT: ${{ github.action_path }}
        COVERAGE_REPORT: ${{ inputs.coverage-report }}
        SOURCE_DIRECTORY: ${{ inputs.source-directory }}
        COVERAGE_FORMAT: ${{ inputs.coverage-format }}
        COVERAGE_CONFIG: ${{ inputs.coverage-config }}
      run: |
        if [[ -n "$COVERAGE_CONFIG" ]]; then
          test -z "$COVERAGE_REPORT"
          test -z "$SOURCE_DIRECTORY"
          node "$CLOUSEAU_ROOT/bin/coverage-gate.cjs" plan "$COVERAGE_CONFIG" "$GITHUB_WORKSPACE"
        else
          test -n "$COVERAGE_REPORT" && test -n "$SOURCE_DIRECTORY"
          node "$CLOUSEAU_ROOT/bin/coverage-gate.cjs" check "$COVERAGE_REPORT" "$SOURCE_DIRECTORY" "$COVERAGE_FORMAT"
        fi
    - name: Verify local review or assess repository intent
      id: assess
      if: inputs.operation == 'assess' || inputs.operation == 'verify-local'
      uses: actions/github-script@v7
      env:
        CLOUSEAU_ROOT: ${{ github.action_path }}
        CLOUSEAU_CONFIG: ${{ inputs.config }}
        DEEPSEEK_API_KEY: ${{ inputs.operation == 'assess' && inputs.provider-key || '' }}
        TYPESAFE_API_KEY: ${{ inputs.operation == 'assess' && inputs.typesafe-key || '' }}
        CLOUSEAU_RECEIPT_ONLY: ${{ inputs.operation == 'verify-local' }}
        PR_NUMBER: ${{ inputs.pull-request }}
        CLOUSEAU_WAIT_FOR_VERIFICATION: ${{ inputs.wait-for-verification }}
        CLOUSEAU_RECORD_TRANSPORT: ${{ inputs.record-transport }}
      with:
        github-token: ${{ inputs.github-token }}
        script: |
          const path = require('node:path');
          const root = process.env.CLOUSEAU_ROOT;
          const config = require(path.join(root, 'src/config.cjs')).loadConfig(process.env.CLOUSEAU_CONFIG);
          const policy = require(path.join(root, 'src/policy.cjs')).createPolicy(config, {engine: require(path.join(root, 'src/central-version.cjs')).environmentEngine()});
          const assess = process.env.CLOUSEAU_WAIT_FOR_VERIFICATION === 'true' ? policy.assessWhenReady : policy.assess;
          const transport = require(path.join(root, 'src/record-transport.cjs'));
          const mode = process.env.CLOUSEAU_RECORD_TRANSPORT;
          let assessment;
          try {
            assessment = await assess({github, context, report: core.info,
              receiptOnly: process.env.CLOUSEAU_RECEIPT_ONLY === 'true'});
          } finally {transport.preserveDiagnostic({mode, core, context, runAttempt: process.env.GITHUB_RUN_ATTEMPT});}
          core.setOutput('assessment', JSON.stringify(assessment));
          require(path.join(root, 'src/incomplete.cjs')).annotate({core, assessment});
          transport.publish({mode, assessment, context, runAttempt: process.env.GITHUB_RUN_ATTEMPT, core});
    - name: Wait for PR verification without holding a stalled runner
      id: await
      if: inputs.operation == 'await-verification'
      uses: actions/github-script@v7
      env:
        CLOUSEAU_ROOT: ${{ github.action_path }}
        CLOUSEAU_CONFIG: ${{ inputs.config }}
        PR_NUMBER: ${{ inputs.pull-request }}
      with:
        github-token: ${{ inputs.github-token }}
        script: |
          const path = require('node:path');
          const root = process.env.CLOUSEAU_ROOT;
          const config = require(path.join(root, 'src/config.cjs')).loadConfig(process.env.CLOUSEAU_CONFIG);
          const policy = require(path.join(root, 'src/policy.cjs')).createPolicy(config, {engine: require(path.join(root, 'src/central-version.cjs')).environmentEngine()});
          await policy.awaitVerification({github, context, core, expectedHead: context.payload.pull_request?.head.sha});
    - name: Approve and ensure auto-merge
      if: inputs.operation == 'gate'
      uses: actions/github-script@v7
      env:
        CLOUSEAU_ROOT: ${{ github.action_path }}
        CLOUSEAU_CONFIG: ${{ inputs.config }}
        PR_NUMBER: ${{ inputs.pull-request }}
        ASSESSMENT: ${{ inputs.assessment }}
        CLOUSEAU_NATIVE_GATE: ${{ inputs.native-gate }}
        CLOUSEAU_RECORD_TRANSPORT: ${{ inputs.record-transport }}
        CLOUSEAU_RECORD_PART_0: ${{ fromJSON(inputs.review-record || '["","","",""]')[0] || '' }}
        CLOUSEAU_RECORD_PART_1: ${{ fromJSON(inputs.review-record || '["","","",""]')[1] || '' }}
        CLOUSEAU_RECORD_PART_2: ${{ fromJSON(inputs.review-record || '["","","",""]')[2] || '' }}
        CLOUSEAU_RECORD_PART_3: ${{ fromJSON(inputs.review-record || '["","","",""]')[3] || '' }}
        CLOUSEAU_RECORD_CANONICAL: >-
          ${{ inputs.review-record == format('[{0},{1},{2},{3}]',
            toJSON(fromJSON(inputs.review-record || '["","","",""]')[0] || ''),
            toJSON(fromJSON(inputs.review-record || '["","","",""]')[1] || ''),
            toJSON(fromJSON(inputs.review-record || '["","","",""]')[2] || ''),
            toJSON(fromJSON(inputs.review-record || '["","","",""]')[3] || '')) }}
      with:
        github-token: ${{ inputs.github-token }}
        script: |
          const path = require('node:path');
          const root = process.env.CLOUSEAU_ROOT;
          const config = require(path.join(root, 'src/config.cjs')).loadConfig(process.env.CLOUSEAU_CONFIG);
          const policy = require(path.join(root, 'src/policy.cjs')).createPolicy(config, {engine: require(path.join(root, 'src/central-version.cjs')).environmentEngine()});
          const transport = require(path.join(root, 'src/record-transport.cjs'));
          const mode = process.env.CLOUSEAU_RECORD_TRANSPORT;
          const payload = mode === 'job-output' ? transport.joinParts([process.env.CLOUSEAU_RECORD_PART_0,
            process.env.CLOUSEAU_RECORD_PART_1, process.env.CLOUSEAU_RECORD_PART_2, process.env.CLOUSEAU_RECORD_PART_3],
            process.env.CLOUSEAU_RECORD_CANONICAL === 'true') : '';
          transport.receive({mode, payload, assessment: JSON.parse(process.env.ASSESSMENT),
            context, runAttempt: process.env.GITHUB_RUN_ATTEMPT});

          await policy.gate({github, context, core, nativeGate: process.env.CLOUSEAU_NATIVE_GATE === 'true'});
    - name: Apply bounded repair with an independent author
      if: inputs.operation == 'repair'
      uses: actions/github-script@v7
      env:
        CLOUSEAU_ROOT: ${{ github.action_path }}
        CLOUSEAU_CONFIG: ${{ inputs.config }}
        CLOUSEAU_REPAIR_TOKEN: ${{ inputs.repair-token }}
        ASSESSMENT: ${{ inputs.assessment }}
        CLOUSEAU_RECORD_TRANSPORT: ${{ inputs.record-transport }}
        CLOUSEAU_RECORD_PART_0: ${{ fromJSON(inputs.review-record || '["","","",""]')[0] || '' }}
        CLOUSEAU_RECORD_PART_1: ${{ fromJSON(inputs.review-record || '["","","",""]')[1] || '' }}
        CLOUSEAU_RECORD_PART_2: ${{ fromJSON(inputs.review-record || '["","","",""]')[2] || '' }}
        CLOUSEAU_RECORD_PART_3: ${{ fromJSON(inputs.review-record || '["","","",""]')[3] || '' }}
        CLOUSEAU_RECORD_CANONICAL: >-
          ${{ inputs.review-record == format('[{0},{1},{2},{3}]',
            toJSON(fromJSON(inputs.review-record || '["","","",""]')[0] || ''),
            toJSON(fromJSON(inputs.review-record || '["","","",""]')[1] || ''),
            toJSON(fromJSON(inputs.review-record || '["","","",""]')[2] || ''),
            toJSON(fromJSON(inputs.review-record || '["","","",""]')[3] || '')) }}
      with:
        github-token: ${{ inputs.github-token }}
        script: |
          const fs = require('node:fs');
          const path = require('node:path');
          const root = process.env.CLOUSEAU_ROOT;
          const controller = require(path.join(root, 'src/acceptance-controller.cjs'));
          const config = require(path.join(root, 'src/config.cjs')).loadConfig(process.env.CLOUSEAU_CONFIG);
          const assessment = JSON.parse(process.env.ASSESSMENT);
          const transport = require(path.join(root, 'src/record-transport.cjs'));
          const mode = process.env.CLOUSEAU_RECORD_TRANSPORT;
          const payload = mode === 'job-output' ? transport.joinParts([process.env.CLOUSEAU_RECORD_PART_0,
            process.env.CLOUSEAU_RECORD_PART_1, process.env.CLOUSEAU_RECORD_PART_2, process.env.CLOUSEAU_RECORD_PART_3],
            process.env.CLOUSEAU_RECORD_CANONICAL === 'true') : '';
          transport.receive({mode, payload, assessment, context, runAttempt: process.env.GITHUB_RUN_ATTEMPT});
          const record = JSON.parse(fs.readFileSync(controller.RECORD, 'utf8'));
          controller.verifyRecord(record, assessment, config, require(path.join(root, 'src/central-version.cjs')).environmentEngine());
          const bundle = JSON.parse(fs.readFileSync(`${controller.RECORD}.repair.json`, 'utf8'));
          if (require(path.join(root, 'src/acceptance.cjs')).digest(bundle) !== assessment.repair_digest) throw new Error('Altered repair artifact');
          if (!process.env.CLOUSEAU_REPAIR_TOKEN) throw new Error('Provide an independent GitHub author credential through repair-token; approval remains blocked');
          const repair = require(path.join(root, 'src/acceptance-repair.cjs'));
          const comments = await github.paginate(github.rest.issues.listComments, {...context.repo, issue_number: assessment.number, per_page: 100});
          const reservations = repair.history(comments, record.snapshot.repository, assessment.number);
          const authorGithub = new github.constructor({auth: process.env.CLOUSEAU_REPAIR_TOKEN});
          const result = await repair.apply({github, authorGithub, context, record, proposal: bundle.proposal, reservations});
          core.info(`Repair revision ${result.head_sha} pushed; fresh CI and independent review are required.`);
    - name: Check DeepSeek provider
      if: inputs.operation == 'check-provider'
      uses: actions/github-script@v7
      env:
        CLOUSEAU_ROOT: ${{ github.action_path }}
        DEEPSEEK_API_KEY: ${{ inputs.provider-key }}
      with:
        github-token: ${{ inputs.github-token }}
        script: |
          const path = require('node:path');
          await require(path.join(process.env.CLOUSEAU_ROOT, 'src/provider.cjs')).checkProvider();
          core.info('DeepSeek authentication and structured output verified. No PR was approved or merged.');
    - name: Evaluate live review decisions
      if: inputs.operation == 'evaluate-review'
      shell: bash
      working-directory: ${{ github.action_path }}
      env:
        DEEPSEEK_API_KEY: ${{ inputs.provider-key }}
      run: node test/evaluate-review.cjs
    - name: Qualify live acceptance decisions and cost
      if: inputs.operation == 'evaluate-acceptance'
      shell: bash
      working-directory: ${{ github.action_path }}
      env:
        DEEPSEEK_API_KEY: ${{ inputs.provider-key }}
        TYPESAFE_API_KEY: ${{ inputs.typesafe-key }}
        CLOUSEAU_EVALUATION_PATH: ${{ github.workspace }}/work/acceptance-evaluation.json
      run: node test/evaluate-acceptance.cjs
    - name: Request trusted metadata reassessment
      if: inputs.operation == 'request-reassessment'
      uses: actions/github-script@v7
      env:
        CLOUSEAU_ROOT: ${{ github.action_path }}
        CLOUSEAU_CONFIG: ${{ inputs.config }}
        PR_NUMBER: ${{ inputs.pull-request }}
      with:
        github-token: ${{ inputs.github-token }}
        script: |
          const path = require('node:path');
          const root = process.env.CLOUSEAU_ROOT;
          const config = require(path.join(root, 'src/config.cjs')).loadConfig(process.env.CLOUSEAU_CONFIG);
          await require(path.join(root, 'src/policy.cjs')).createPolicy(config, {engine: require(path.join(root, 'src/central-version.cjs')).environmentEngine()}).requestReassessment({github, context, core});
    - name: Finalize merged revision and preserve deployment handoff
      if: inputs.operation == 'finalize'
      uses: actions/github-script@v7
      env:
        CLOUSEAU_ROOT: ${{ github.action_path }}
        CLOUSEAU_CONFIG: ${{ inputs.config }}
        PR_NUMBER: ${{ inputs.pull-request }}
        ASSESSMENT: ${{ inputs.assessment }}
      with:
        github-token: ${{ inputs.github-token }}
        script: |
          const path = require('node:path');
          const root = process.env.CLOUSEAU_ROOT;
          const config = require(path.join(root, 'src/config.cjs')).loadConfig(process.env.CLOUSEAU_CONFIG);
          await require(path.join(root, 'src/policy.cjs')).createPolicy(config, {engine: require(path.join(root, 'src/central-version.cjs')).environmentEngine()}).finalize({github, context, core});

    - name: Prepare coordinated wiki documentation
      id: plan-wiki
      if: inputs.operation == 'plan-wiki'
      uses: actions/github-script@v7
      env:
        CLOUSEAU_ROOT: ${{ github.action_path }}
        WIKI_CONFIG: ${{ inputs.wiki-config }}
        WIKI_DIRECTORY: ${{ inputs.wiki-directory }}
        WIKI_SOURCE_DIRECTORY: ${{ inputs.wiki-source-directory }}
        WIKI_PLAN_PATH: ${{ inputs.wiki-plan-path }}
        WIKI_DRAFT: ${{ inputs.wiki-draft }}
        DEEPSEEK_API_KEY: ${{ inputs.provider-key }}
      with:
        github-token: ${{ inputs.github-token }}
        script: |
          const fs = require('node:fs');
          const path = require('node:path');
          if (!process.env.DEEPSEEK_API_KEY) throw new Error('DEEPSEEK_API_KEY is not configured');
          const config = JSON.parse(fs.readFileSync(process.env.WIKI_CONFIG, 'utf8'));
          fs.mkdirSync(path.dirname(process.env.WIKI_PLAN_PATH), {recursive: true});
          const diagnostics = [];
          const bundle = await require(path.join(process.env.CLOUSEAU_ROOT, 'src/wiki-git.cjs')).prepareWiki({
            github, context, config, sourceDirectory: process.env.WIKI_SOURCE_DIRECTORY,
            wikiDirectory: process.env.WIKI_DIRECTORY, draft: process.env.WIKI_DRAFT === 'true',
            report: line => core.info(line.replace(/^AI assessment/, 'Wiki generation')),
            diagnostic: result => {
              diagnostics.push(result);
              fs.writeFileSync(`${process.env.WIKI_PLAN_PATH}.diagnostic.json`, JSON.stringify({version: 1, reviews: diagnostics}, null, 2) + '\n');
            }});
          fs.writeFileSync(process.env.WIKI_PLAN_PATH, JSON.stringify(bundle, null, 2) + '\n');
          core.info(`Validated coordinated update for ${bundle.updates.length} wiki pages. Nothing published.`);
    - name: Publish validated wiki documentation
      id: publish-wiki
      if: inputs.operation == 'publish-wiki'
      uses: actions/github-script@v7
      env:
        CLOUSEAU_ROOT: ${{ github.action_path }}
        WIKI_CONFIG: ${{ inputs.wiki-config }}
        WIKI_DIRECTORY: ${{ inputs.wiki-directory }}
        WIKI_SOURCE_DIRECTORY: ${{ inputs.wiki-source-directory }}
        WIKI_PLAN_PATH: ${{ inputs.wiki-plan-path }}
      with:
        github-token: ${{ inputs.github-token }}
        script: |
          const fs = require('node:fs');
          const path = require('node:path');
          const config = JSON.parse(fs.readFileSync(process.env.WIKI_CONFIG, 'utf8'));
          const bundle = JSON.parse(fs.readFileSync(process.env.WIKI_PLAN_PATH, 'utf8'));
          const result = await require(path.join(process.env.CLOUSEAU_ROOT, 'src/wiki-git.cjs')).publishWiki({
            github, context, config, sourceDirectory: process.env.WIKI_SOURCE_DIRECTORY,
            wikiDirectory: process.env.WIKI_DIRECTORY, bundle});
          core.setOutput('commit', result.commit);
          core.setOutput('pages', result.changedPages);
          await core.summary.addRaw(`Wiki documentation: ${result.changedPages} Markdown pages changed. Wiki commit: ${result.commit}. Source revision: ${context.sha}. This is not a live-health assertion.`).write();

    - name: Evaluate wiki factual review against supported and false claims
      if: inputs.operation == 'evaluate-wiki'
      uses: actions/github-script@v7
      env:
        CLOUSEAU_ROOT: ${{ github.action_path }}
        WIKI_PLAN_PATH: ${{ inputs.wiki-plan-path }}
        DEEPSEEK_API_KEY: ${{ inputs.provider-key }}
      with:
        github-token: ${{ inputs.github-token }}
        script: |
          if (!process.env.DEEPSEEK_API_KEY) throw new Error('DEEPSEEK_API_KEY is not configured');
          const fs = require('node:fs');
          const path = require('node:path');
          const output = `${process.env.WIKI_PLAN_PATH}.evaluation.json`;
          const cases = [];
          fs.mkdirSync(path.dirname(output), {recursive: true});
          fs.writeFileSync(output, JSON.stringify({version: 1, cases}, null, 2) + '\n');
          await require(path.join(process.env.CLOUSEAU_ROOT, 'src/wiki.cjs')).evaluateWiki({report: line => core.info(line),
            diagnostic: result => {cases.push(result); fs.writeFileSync(output, JSON.stringify({version: 1, cases}, null, 2) + '\n');}});

